function definirTabela6(divisao){return MAPA_TABELAS_6[divisao]||null;}
function obterColunaAlturaTabela6(altura,pavimentos){if(Number(pavimentos)<=1)return "terrea";const h=Number(altura);if(h<=6)return "ate6";if(h<=12)return "de6a12";if(h<=23)return "de12a23";if(h<=30)return "de23a30";return "acima30";}
function simplificarNotaTabela6(texto){return String(texto||"").replace(/^Nota geral [a-z]:\s*/i,"").replace(/área total construída/gi,"área total do prédio").replace(/garagens internas/gi,"garagens dentro do prédio").replace(/sistema de chuveiros automáticos/gi,"chuveiros automáticos").replace(/m 2/g,"m²").trim();}
function avaliarCondicaoNota6(texto,dados={},divisao=""){
 const t=String(texto||"").normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase();
 if(/nota geral/.test(t)&&/subsolos?/.test(t))return Number(dados.areaSubsolo)>0?"informativa":"irrelevante";
 if(/nota geral/.test(t)&&/subsolos?/.test(t))return Number(dados.areaSubsolo)>0?"informativa":"irrelevante";
 if(/brigada/.test(t)&&/recomendatorio/.test(t)&&/c-2/.test(t)&&/5000/.test(t)){
  if(divisao==="C-1")return "informativa";
  if(["C-2","C-3"].includes(divisao))return Number(dados.area)>=5000?"aplicavel":"nao-aplicavel";
 }
 if(/depositos?/.test(t)&&/750/.test(t)&&/(deteccao|alarme)/.test(t)){
  const area=dados.areaDeposito===null||dados.areaDeposito===undefined||dados.areaDeposito===""?NaN:Number(dados.areaDeposito);
  if(Number.isFinite(area))return area>750?"aplicavel":"nao-aplicavel";
  const identificado=Boolean(dados.armazenamento)||dados.usoSubsolo==="deposito";
  return identificado?"dados-faltantes":"nao-aplicavel";
 }
 if(/garagens? internas?/.test(t)&&/(750|superior|acima|exigid)/.test(t)&&/garagens internas/.test(t)){
  if(Number(dados.areaSubsolo)>0&&dados.usoSubsolo&&dados.usoSubsolo!=="estacionamento"&&/subsolo/.test(t)&&/(estacionamento|garagem)/.test(t))return "nao-aplicavel";
  if(dados.areaGaragemInterna===null||dados.areaGaragemInterna===undefined||dados.areaGaragemInterna==="")return "dados-faltantes";
  return Number(dados.areaGaragemInterna)>750?"aplicavel":"nao-aplicavel";
 }
 let m=t.match(/(?:altura|acima de|maior que)\s*(?:de\s*)?(\d+)\s*m/);
 if(m&&/altura|acima de|maior que/.test(t)){if(dados.altura===undefined||dados.altura===null)return "dados-faltantes";return Number(dados.altura)>Number(m[1])?"aplicavel":"nao-aplicavel";}
 m=t.match(/(?:area total(?: construida)?|area da edificacao)[^\d]*(?:igual ou superior a|superior a|acima de|a partir de)\s*([\d.]+)\s*m\s*(?:2|²)/);
 if(m){if(dados.area===undefined||dados.area===null)return "dados-faltantes";return Number(dados.area)>=Number(m[1].replace(/\./g,""))?"aplicavel":"nao-aplicavel";}
 m=t.match(/(?:publico|concentracao de publico|lotacao)[^\d]*(?:a partir de|superior a|acima de|inferior a)\s*(\d+)/);
 if(m){const x=divisao==="F-7"?dados.publicoEvento:dados.lotacao;if(x===undefined||x===null)return "dados-faltantes";return Number(x)>=Number(m[1])?"aplicavel":"nao-aplicavel";}
 if(/brigada/.test(t)&&/c-1/.test(t)&&/c-2/.test(t)&&/5\.000|5000/.test(t)){
  if(divisao==="C-1")return "informativa";
  if(["C-2","C-3"].includes(divisao))return Number(dados.area)>=5000?"aplicavel":"nao-aplicavel";
 }
 if(/pode ser substituid|podera ser substituid|recomendatori[oa]/.test(t))return "informativa";
 if(/somente|apenas|nos quartos|nos dormitorios|nas unidades autonomas|haja carga de incendio|locais onde|quando houver|quando for|quando possuirem|quando instalado/.test(t))return "dados-faltantes";
 return "informativa";
}
function interpretarMarcacaoTabela6(marcacao,codigoTabela,divisao,dados={}){
 const valor=String(marcacao||"");if(!/^X(?:\d+(?:,\d+)*)?$/.test(valor))return {estado:"naoExigida",marcacao:valor||"-",notas:[],condicoes:[],mostrar:false};
 const numeros=[...valor.matchAll(/\d+/g)].map(x=>Number(x[0]));
 const textos=codigoTabela==="6C"?NOTAS_TABELA_6C:codigoTabela==="6A"?NOTAS_TABELA_6A:codigoTabela==="6B"?NOTAS_TABELA_6B:(NOTAS_MATRIZES_TABELA_6[codigoTabela]||[]);
 const notas=numeros.map(n=>({numero:n,texto:textos[n-1]||`Nota ${n} da ${codigoTabela}: confirme na publicação oficial.`}));
 const avaliacoes=notas.map(n=>({...n,aplicacao:avaliarCondicaoNota6(n.texto,dados,divisao)}));
 if(avaliacoes.some(n=>n.aplicacao==="nao-aplicavel"))return {estado:"naoExigida",marcacao:valor,notas:numeros,condicoes:[],mostrar:false};
 if(avaliacoes.some(n=>n.aplicacao==="dados-faltantes"))return {estado:"indeterminada",marcacao:valor,notas:numeros,condicoes:[],mostrar:false};
 return {estado:"exigida",marcacao:valor,notas:numeros,condicoes:avaliacoes.map(n=>simplificarNotaTabela6(n.texto)),mostrar:true};
}
function obterMedidasTabela6C(divisao,altura,pavimentos,dados={}){return obterMedidasMatrizTabela6("6C",altura,pavimentos,divisao,dados);}
function obterMedidasMatrizTabela6(tabela,altura,pavimentos,divisao,dados={}){const col=ALTURAS_TABELA_6.indexOf(obterColunaAlturaTabela6(altura,pavimentos));return MEDIDAS_6.map((nome,i)=>({nome,...interpretarMarcacaoTabela6(MATRIZES_TABELA_6[tabela][i][col],tabela,divisao,dados)}));}
function obterAlertasTabela6C(dados={}){const a=[];if(Number(dados.alturaExpositores)>3.7)a.push({tipo:"alerta",texto:NOTAS_TABELA_6C[0]});if(Number(dados.areaDeposito)>750)a.push({tipo:"alerta",texto:NOTAS_TABELA_6C[6]});return a;}
