 if(tabela==="6M.1"){const n=Number(dados.comprimentoTunel);if(!n)return {tabela,pendente:true,medidas:[],observacao:"Informe a extensão do túnel para selecionar a coluna da Tabela 6M.1.",notas:extra.notas};indices=[n<=200?0:n<=500?1:n<=1000?2:3];cabecalhos=COLUNAS_ESPECIAIS_6[tabela];}
